drop policy if exists financial_documents_investor_select_published on storage.objects;
create policy financial_documents_investor_select_published on storage.objects for select to authenticated using (bucket_id='financial-documents' and app.current_investor_id() is not null and exists (select 1 from public.media_assets a join public.financial_report_versions fv on fv.document_asset_id=a.id join public.financial_reports fr on fr.id=fv.financial_report_id join public.financial_periods fp on fp.id=fr.financial_period_id where a.bucket='financial-documents' and a.path=objects.name and a.finalized_at is not null and fr.status='published' and fr.visibility='investors' and fr.published_version_id=fv.id and fv.status='published' and fp.status in ('closed','locked')));
create or replace function app.list_investor_financial_reports() returns table(report_id uuid,title text,period_start date,period_end date,published_at timestamptz,storage_path text,original_filename text) language sql stable security definer set search_path='' as $$select fr.id,fr.title,fp.starts_on,fp.ends_on,fv.published_at,a.path,a.original_filename from public.financial_reports fr join public.financial_periods fp on fp.id=fr.financial_period_id join public.financial_report_versions fv on fv.id=fr.published_version_id and fv.financial_report_id=fr.id join public.media_assets a on a.id=fv.document_asset_id where app.current_investor_id() is not null and fr.status='published' and fr.visibility='investors' and fv.status='published' and fp.status in ('closed','locked') and a.bucket='financial-documents' and a.finalized_at is not null order by fp.ends_on desc,fr.created_at desc$$;
revoke execute on function app.list_investor_financial_reports() from public,anon;
grant execute on function app.list_investor_financial_reports() to authenticated;